  8	const EXPENSE_FIELDS = ['type', 'description', 'payer', 'amount', 'split']
  9	const PAYMENT_FIELDS = ['type', 'from', 'to', 'amount']
 10	const MAX_ENTRIES = 50
 11	
 12	const isObject = v => v !== null && typeof v === 'object' && !Array.isArray(v)
 13	
 14	// Thrown by checkEntry with the first rule an entry breaks.
 15	class Broken extends Error {
 16	  constructor(rule) {
 17	    super(rule)
 18	    this.rule = rule
 19	  }
 20	}
 21	
 22	// Runs one of the POST routes' parsers, turning its ValidationError into the import rule it stands for.
 23	function parseAs(rule, parse) {
 24	  try {
 25	    return parse()
 26	  } catch (err) {
 27	    if (err instanceof ValidationError) throw new Broken(rule)
 28	    throw err
 29	  }
 30	}
 31	
 32	// The body's own checks, in order; the first one that fails is the 400 message. Returns the import options.
 33	function parseImportBody(body) {
 34	  const unknown = Object.keys(body).find(key => !BODY_FIELDS.includes(key))
 35	  if (unknown !== undefined) throw new ValidationError(`unknown field ${unknown}`)
 36	  const { entries } = body
 37	  if (!Array.isArray(entries) || entries.length < 1 || entries.length > MAX_ENTRIES) {
 38	    throw new ValidationError(`entries must be an array of 1 to ${MAX_ENTRIES} items`)
 39	  }
 40	  const flag = name => {
 41	    if (!Object.hasOwn(body, name)) return false
 42	    if (typeof body[name] !== 'boolean') throw new ValidationError(`${name} must be true or false`)
 43	    return body[name]
 44	  }
 45	  return { entries, dryRun: flag('dry_run'), skipRecorded: flag('skip_recorded') }
 46	}
 47	
 48	// One entry's fields, checked by the same rules as POST /groups/:id/expenses or /payments. Throws Broken with
 49	// the first field rule the entry breaks; duplicates are found later, by the caller.
 50	function checkEntry(entry, group) {
 51	  if (!isObject(entry)) throw new Broken('not-an-object')
 52	  if (entry.type !== 'expense' && entry.type !== 'payment') throw new Broken('bad-type')
 53	  const fields = entry.type === 'expense' ? EXPENSE_FIELDS : PAYMENT_FIELDS
 54	  if (Object.keys(entry).some(key => !fields.includes(key))) throw new Broken('unknown-field')
 55	  if (entry.type === 'expense') {
 56	    return {
 57	      type: 'expense',
 58	      description: parseAs('bad-description', () => parseDescription(entry.description)),
 59	      payer: parseAs('bad-payer', () => parseMember(entry.payer, group.members, 'bad payer')),
 60	      amount: parseAs('bad-amount', () => parseAmount(entry.amount)),
 61	      split: parseAs('bad-split', () => parseSplit(entry.split, group.members)),
 62	    }
 63	  }
 64	  const from = parseAs('bad-from', () => parseMember(entry.from, group.members, 'bad from'))
 65	  const to = parseAs('bad-to', () => parseMember(entry.to, group.members, 'bad to'))
 66	  if (to === from) throw new Broken('bad-to')
 67	  return { type: 'payment', from, to, amount: parseAs('bad-amount', () => parseAmount(entry.amount)) }
 68	}
 69	
 70	// Two expenses are the same when payer, amount in cents and description (trimmed, lower case) match.
 71	const sameKey = ({ payer, amount, description }) => JSON.stringify([payer, amount, description.trim().toLowerCase()])
 72	
 73	// The first rule an entry breaks, duplicates included, or null when it has none. `seen` holds the keys of the
 74	// earlier entries that passed the field rules; this entry's key is added to it.
 75	function brokenRule(parsed, seen, recorded) {
 76	  if (parsed.type !== 'expense') return null
 77	  const key = sameKey(parsed)
 78	  if (seen.has(key)) return 'duplicate'
 79	  seen.add(key)
 80	  return recorded.has(key) ? 'already-recorded' : null
 81	}
 82	
 83	// Sorts the entries into problems [{index, rule}], skipped indexes and the parsed entries to import.
 84	function classifyEntries(entries, group, recordedExpenses, skipRecorded) {
 85	  const recorded = new Set(recordedExpenses.map(sameKey))
 86	  const seen = new Set()
 87	  const problems = []
 88	  const skipped = []
 89	  const accepted = []
 90	  entries.forEach((entry, index) => {
 91	    let parsed = null
 92	    let rule
 93	    try {
 94	      parsed = checkEntry(entry, group)
 95	      rule = brokenRule(parsed, seen, recorded)
 96	    } catch (err) {
 97	      if (!(err instanceof Broken)) throw err
 98	      rule = err.rule
 99	    }
100	    if (rule === 'already-recorded' && skipRecorded) skipped.push(index)
101	    else if (rule) problems.push({ index, rule })
102	    else accepted.push(parsed)
103	  })
104	  return { problems, skipped, accepted }
105	}
106	
107	// The stored expenses and payments for the accepted entries, each kind numbered on from its next id.
108	function numberEntries(accepted, state, groupId) {
109	  const expenses = []
110	  const payments = []
111	  for (const { type, ...fields } of accepted) {
112	    if (type === 'expense') expenses.push({ id: state.nextExpenseId + expenses.length, group: groupId, ...fields })
113	    else payments.push({ id: state.nextPaymentId + payments.length, group: groupId, ...fields })
114	  }
115	  return { expenses, payments }
116	}
117	
118	export function importEntries({ state, params, body }) {
119	  const group = findGroup(state, params[0])
120	  if (!group) return NOT_FOUND
121	  const { entries, dryRun, skipRecorded } = parseImportBody(body)
122	  const recordedExpenses = state.expenses.filter(e => e.group === group.id)
123	  const { problems, skipped, accepted } = classifyEntries(entries, group, recordedExpenses, skipRecorded)
124	  if (problems.length > 0) return { status: 422, body: { error: 'import rejected', problems } }
125	
126	  const { expenses, payments } = numberEntries(accepted, state, group.id)
127	  const next = {
128	    ...state,
129	    expenses: [...state.expenses, ...expenses],
130	    payments: [...state.payments, ...payments],
131	    nextExpenseId: state.nextExpenseId + expenses.length,
132	    nextPaymentId: state.nextPaymentId + payments.length,
133	  }
134	  const reply = {
135	    status: dryRun ? 200 : 201,
136	    body: { expenses: expenses.map(expenseView), payments: payments.map(paymentView), skipped, balances: balances(next, group) },
137	  }
138	  // A dry run, or an import whose entries were all skipped, leaves the store and the data file as they are.
139	  return dryRun || accepted.length === 0 ? reply : { ...reply, state: next }
140	}

