eq('arr body', (await I('[]'))[0], 400)
eq('413', (await I(JSON.stringify({ entries: [e({ description: 'x'.repeat(11000) })] })))[0], 413)
const rules = await I({ entries: [null, [], 5, { type: 'x' }, { type: ['expense'] }, e({ foo: 1 }), p({ split: [] }), e({ description: '  ' }), e({ payer: 'Zed' }), e({ amount: 1.234 }), e({ split: null }), e({ split: [] }), p({ from: 'Zed' }), p({ to: 'Ben' }), p({ to: 'Zed' }), p({ amount: 0 }), e({ description: null, payer: null }), e({ split: ['Ann', 'Ann'] }), { type: 'payment', from: 'Ann', to: 'Ben', amount: 1, description: 'x' }, e({ amount: '12' })] })
eq('rules', rules, [422, { error: 'import rejected', problems: [[0,'not-an-object'],[1,'not-an-object'],[2,'not-an-object'],[3,'bad-type'],[4,'bad-type'],[5,'unknown-field'],[6,'unknown-field'],[7,'bad-description'],[8,'bad-payer'],[9,'bad-amount'],[10,'bad-split'],[11,'bad-split'],[12,'bad-from'],[13,'bad-to'],[14,'bad-to'],[15,'bad-amount'],[16,'bad-description'],[17,'bad-split'],[18,'unknown-field'],[19,'bad-amount']].map(([index, rule]) => ({ index, rule })) }])
