eq('balances match', real[1].balances, (await call('GET', '/groups/trip/balances'))[1].balances)
eq('keys', Object.keys(real[1]), ['expenses', 'payments', 'skipped', 'balances'])
eq('next id', (await call('POST', '/groups/trip/expenses', { description: 'b', payer: 'Ann', amount: 1 }))[1].id, E + 2)
eq('persist', JSON.parse(readFileSync(file, 'utf8')).nextPaymentId, P + 2)
// identical payments allowed
eq('pay dup', (await I({ entries: [p(), p()] }))[0], 201)
// split order preserved / default split
eq('default split', (await I({ entries: [e({ description: 'Z9', amount: 0.05 })], dry_run: true }))[1].expenses[0].shares, { Ann: 0.02, Ben: 0.02, Cara: 0.01 })
// proto
eq('proto', await I(JSON.stringify({ entries: [{ type: 'expense', description: 'q', payer: 'Ann', amount: 1, __proto__: {} }] })), [422, { error: 'import rejected', problems: [{ index: 0, rule: 'unknown-field' }] }])
eq('type constructor', (await I({ entries: [{ type: 'constructor' }, { type: 'toString' }, { type: '__proto__' }] }))[1].problems?.map(x => x.rule), ['bad-type', 'bad-type', 'bad-type'])
// other route still ignores unknown fields
eq('ignore unknown', (await call('POST', '/groups/trip/expenses', { description: 'c', payer: 'Ann', amount: 1, zz: 1 }))[0], 201)
console.log(root, 'fails', fails)
server.close()
