import { cpSync, mkdtempSync, readFileSync, writeFileSync } from @node:fs@
import { tmpdir } from @node:os@
import { join } from @node:path@
import { spawnSync } from @node:child_process@
const WRAP = `
const __M = process.env.MUTANT
function __wrap(h) {
  return ctx => {
    let body = ctx.body
    if (__M === @nullflag@) { body = { ...body }; for (const k of [@dry_run@, @skip_recorded@]) if (body[k] === null) delete body[k] }
    if (__M === @nullsplit@ && Array.isArray(body.entries)) body = { ...body, entries: body.entries.map(e => e && e.split === null ? (({ split, ...r }) => r)(e) : e) }
    if (__M === @arrayobj@ && Array.isArray(body.entries)) body = { ...body, entries: body.entries.map(e => Array.isArray(e) ? { type: @expense@ } : e) }
    if (__M === @unknownok@ && Array.isArray(body.entries)) body = { ...body, entries: body.entries.map(e => e && typeof e === @object@ && !Array.isArray(e) ? Object.fromEntries(Object.entries(e).filter(([k]) => [@type@, @description@, @payer@, @amount@, @split@, @from@, @to@].includes(k))) : e) }
    if (__M === @noskip@ && body.skip_recorded === true) body = { ...body, skip_recorded: false }
    if (__M === @order404@ && !ctx.state.groups.find(g => g.id === ctx.params[0]) && Object.keys(body).some(k => ![@entries@, @dry_run@, @skip_recorded@].includes(k))) return { status: 400, body: { error: @unknown field x@ } }
    let r = h({ ...ctx, body })
    if (__M === @drysaves@ && body.dry_run === true && r.status === 200) { const r2 = h({ ...ctx, body: { ...body, dry_run: false } }); r = { ...r, state: r2.state } }
    if (__M === @dry201@ && r.status === 200) r = { ...r, status: 201 }
    if (__M === @skipwrites@ && r.status === 201 && !r.state) r = { ...r, state: { ...ctx.state } }
    if (__M === @revskip@ && r.body && Array.isArray(r.body.skipped)) r = { ...r, body: { ...r.body, skipped: [...r.body.skipped].reverse() } }
    if (__M === @revprob@ && r.body && Array.isArray(r.body.problems)) r = { ...r, body: { ...r.body, problems: [...r.body.problems].reverse() } }
    if (__M === @firstprob@ && r.body && Array.isArray(r.body.problems)) r = { ...r, body: { ...r.body, problems: r.body.problems.slice(0, 1) } }
    if (__M === @nestbal@ && r.body && r.body.balances) r = { ...r, body: { ...r.body, balances: { balances: r.body.balances } } }
    if (__M === @nobal@ && r.body && r.body.balances) r = { ...r, body: { ...r.body, balances: ctx.state.groups.length ? Object.fromEntries(Object.keys(r.body.balances).map(k => [k, 0])) : r.body.balances } }
    return r
  }
}
`
const SRC = {
  revertsplit: [@lib/ledger.mjs@, /return people.map\(\(name, i\).*\n/, @return people.map(name => [name, share])\n@],
  revertround: [@lib/validate.mjs@, /Math.round\(v \* CENTS_PER_UNIT\)/, @Math.trunc(v * CENTS_PER_UNIT)@],
  noseen: [@lib/import.mjs@, /seen\.add\(key\)/, @0@],
  notrim: [@lib/import.mjs@, /description\.trim\(\)\.toLowerCase\(\)/, @description@],
}
const muts = [@nullflag@, @nullsplit@, @arrayobj@, @unknownok@, @noskip@, @order404@, @drysaves@, @dry201@, @skipwrites@, @revskip@, @revprob@, @firstprob@, @nestbal@, @nobal@, ...Object.keys(SRC)]
for (const label of [@W@, @X@, @Y@, @Z@]) {
  const killed = [], survived = []
  for (const m of muts) {
    const d = mkdtempSync(join(tmpdir(), @mut-@))
    cpSync(join(process.cwd(), label), d, { recursive: true })
    const rp = join(d, @lib/routes.mjs@)
    writeFileSync(rp, readFileSync(rp, @utf8@).replace(@handler: importEntries@, @handler: __wrap(importEntries)@) + WRAP)
    if (SRC[m]) { const [f, re, rep] = SRC[m]; const p = join(d, f); const s = readFileSync(p, @utf8@); const n = s.replace(re, rep); if (n === s) console.log(label, m, @NO-APPLY@); writeFileSync(p, n) }
    const res = spawnSync(@node@, [@--test@, @test/*.test.mjs@], { cwd: d, env: { ...process.env, MUTANT: m }, encoding: @utf8@ })
    ;(res.status === 0 ? survived : killed).push(m)
  }
  console.log(label, @killed@, killed.length, @/@, muts.length, @survived:@, survived.join(@,@))
}
EOF

